CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Sales_vSalesPersonSalesByFiscalYears` AS select `soh`.`SalesPersonID` AS `SalesPersonID`,`soh`.`FullName` AS `FullName`,`soh`.`JobTitle` AS `JobTitle`,`soh`.`SalesTerritory` AS `SalesTerritory`,sum((case when (`soh`.`FiscalYear` = 2002) then `soh`.`SubTotal` else NULL end)) AS `2002`,sum((case when (`soh`.`FiscalYear` = 2003) then `soh`.`SubTotal` else NULL end)) AS `2003`,sum((case when (`soh`.`FiscalYear` = 2004) then `soh`.`SubTotal` else NULL end)) AS `2004` from (select `soh`.`SalesPersonID` AS `SalesPersonID`,concat(`p`.`FirstName`,' ',coalesce(`p`.`MiddleName`,''),' ',`p`.`LastName`) AS `FullName`,`e`.`JobTitle` AS `JobTitle`,`st`.`Name` AS `SalesTerritory`,`soh`.`SubTotal` AS `SubTotal`,year((`soh`.`OrderDate` + interval 6 month)) AS `FiscalYear` from ((((`Sales_SalesPerson` `sp` join `Sales_SalesOrderHeader` `soh` on((`sp`.`BusinessEntityID` = `soh`.`SalesPersonID`))) join `Sales_SalesTerritory` `st` on((`sp`.`TerritoryID` = `st`.`TerritoryID`))) join `HumanResources_Employee` `e` on((`soh`.`SalesPersonID` = `e`.`BusinessEntityID`))) join `Person_Person` `p` on((`p`.`BusinessEntityID` = `sp`.`BusinessEntityID`)))) `soh` group by `soh`.`SalesPersonID`,`soh`.`FullName`,`soh`.`JobTitle`,`soh`.`SalesTerritory`;
